#include "gear/GearProgressionTransaction.hpp"
#include "core/Saturating.hpp"
namespace elysium::gear {namespace{constexpr std::uint64_t Provider=0x474541525458ULL;}
ReforgeTransactionPlan GearProgressionTransactionPlanner::planReforge(const ReforgeTransactionRequest&r,const rpg::GearItemState&item,const rpg::GearItemDefinition&def)const{ReforgeTransactionPlan o{};o.resultingItem=item;if(!r.transactionId||!r.itemStableId){o.reasons.add({reason::ReasonCode::InvalidRequest,Provider,r.itemStableId,0});return o;}auto result=rpg::reforgeGear(o.resultingItem,def,safe::nonNegative(r.reforgeScale),r.entropy);if(!result.success){o.reasons.add({reason::ReasonCode::InvalidRequest,Provider,r.itemStableId,10});return o;}o.accepted=true;return o;}
AscensionTransactionPlan GearProgressionTransactionPlanner::planAscension(const AscensionTransactionRequest&r,const rpg::GearItemState&t,const rpg::GearItemState&c,const rpg::GearItemDefinition&def)const{AscensionTransactionPlan o{};o.resultingTarget=t;o.resultingCounterpart=c;if(!r.transactionId||!r.targetStableId||!r.counterpartStableId||r.targetStableId==r.counterpartStableId){o.reasons.add({reason::ReasonCode::InvalidRequest,Provider,r.targetStableId,0});return o;}auto result=rpg::ascendGear(o.resultingTarget,o.resultingCounterpart,def);if(!result.success){o.reasons.add({reason::ReasonCode::MissingInput,Provider,r.counterpartStableId,10});return o;}o.accepted=true;return o;}
bool GearTransactionLedger::commit(std::uint64_t id){return id&&ids_.insert(id).second;}bool GearTransactionLedger::seen(std::uint64_t id)const{return id&&ids_.contains(id);}
} // namespace elysium::gear
